mapper.select:
select count(1)
from litemall_agent_rag_evidence e
inner join litemall_agent_rag_run r on r.id = e.run_id
where e.tenant_id = #{tenantId}
  and r.tenant_id = #{tenantId}
  and r.deleted = 0
  and r.evidence_expires_at is not null
  and r.evidence_expires_at <= #{now}
  and (e.evidence_expired is null or e.evidence_expired = 0)

select 
from litemall_agent_rag_evidence e
inner join litemall_agent_rag_run r on r.id = e.run_id
where e.tenant_id = #{tenantId}
  and r.tenant_id = #{tenantId}
  and r.deleted = 0
  and r.evidence_expires_at is not null
  and r.evidence_expires_at <= #{now}
  and (e.evidence_expired is null or e.evidence_expired = 0)
order by r.evidence_expires_at asc, e.id asc
limit #{limit}

mapper.update:
update litemall_agent_rag_evidence
set bounded_json = #{boundedJson},
    payload_size_bytes = #{payloadSizeBytes},
    evidence_expired = 1,
    expired_at = #{expiredAt}
where tenant_id = #{tenantId}
  and run_id = #{runId}
  and (evidence_expired is null or evidence_expired = 0)
